import path from "path"
import { Effect, Option, Schema } from "effect"
import { FSUtil } from "@opencode-ai/core/fs-util"
import { InstanceState } from "@/effect/instance-state"
import { LANGUAGE_EXTENSIONS } from "@/lsp/language"
import { Tool } from "./tool"
import DESCRIPTION from "./repository-overview.txt"

const EXCLUDED = new Set([
  "node_modules",
  ".git",
  "dist",
  "build",
  "coverage",
  ".next",
  ".nuxt",
  ".turbo",
  ".cache",
  "target",
  "vendor",
  ".venv",
  "venv",
  "__pycache__",
])

const FILES = new Map<string, "manifest" | "lockfile" | "config">([
  ["package.json", "manifest"],
  ["pyproject.toml", "manifest"],
  ["Cargo.toml", "manifest"],
  ["go.mod", "manifest"],
  ["bun.lock", "lockfile"],
  ["bun.lockb", "lockfile"],
  ["package-lock.json", "lockfile"],
  ["pnpm-lock.yaml", "lockfile"],
  ["yarn.lock", "lockfile"],
  ["tsconfig.json", "config"],
  ["jsconfig.json", "config"],
  ["vite.config.ts", "config"],
  ["vite.config.js", "config"],
  ["vite.config.mts", "config"],
  ["vite.config.mjs", "config"],
  ["next.config.js", "config"],
  ["next.config.mjs", "config"],
  ["next.config.ts", "config"],
])

export const Parameters = Schema.Struct({})

export const MAX_COLLECTION_ITEMS = 100
export const MAX_WORKSPACE_STEPS = 1000
export const MAX_TECHNOLOGY_DIRECTORIES = 1000
export const MAX_TEXT_LENGTH = 1024
export const MAX_OUTPUT_BYTES = 32 * 1024

const PackageMetadata = Schema.Struct({
  name: Schema.optional(Schema.Unknown),
  packageManager: Schema.optional(Schema.Unknown),
  workspaces: Schema.optional(Schema.Unknown),
  dependencies: Schema.optional(Schema.Unknown),
  devDependencies: Schema.optional(Schema.Unknown),
})

const LANGUAGES = new Map([
  ["typescript", "TypeScript"],
  ["typescriptreact", "TypeScript"],
  ["javascript", "JavaScript"],
  ["javascriptreact", "JavaScript"],
  ["python", "Python"],
  ["go", "Go"],
  ["rust", "Rust"],
  ["java", "Java"],
])

const LANGUAGE_FILES = new Map([
  ["tsconfig.json", "TypeScript"],
  ["jsconfig.json", "JavaScript"],
  ["pyproject.toml", "Python"],
  ["Cargo.toml", "Rust"],
  ["go.mod", "Go"],
  ["pom.xml", "Java"],
  ["build.gradle", "Java"],
  ["build.gradle.kts", "Java"],
])

const FRAMEWORKS = new Map([
  ["react", "React"],
  ["next", "Next.js"],
  ["vue", "Vue"],
  ["svelte", "Svelte"],
  ["@angular/core", "Angular"],
  ["express", "Express"],
])

const WorkspaceDeclaration = Schema.Union([
  Schema.Array(Schema.String),
  Schema.Struct({ packages: Schema.Array(Schema.String) }),
])

const MANAGERS = new Map([
  ["bun.lock", "bun"],
  ["bun.lockb", "bun"],
  ["pnpm-lock.yaml", "pnpm"],
  ["yarn.lock", "yarn"],
  ["package-lock.json", "npm"],
])

export const RepositoryOverviewTool = Tool.define(
  "repository_overview",
  Effect.gen(function* () {
    const fs = yield* FSUtil.Service
    return {
      description: DESCRIPTION,
      parameters: Parameters,
      execute: (_params, ctx) =>
        Effect.gen(function* () {
          const instance = yield* InstanceState.context
          const readPackageMetadata = (directory: string) => {
            const file = path.join(directory, "package.json")
            return Effect.gen(function* () {
              yield* ctx.ask({
                permission: "read",
                patterns: [path.relative(instance.worktree, file)],
                always: ["*"],
                metadata: { path: file },
              })
              return yield* fs.readJson(file).pipe(
                Effect.map(Schema.decodeUnknownOption(PackageMetadata)),
                Effect.map(Option.getOrNull),
                Effect.catch(() => Effect.succeed(null)),
              )
            })
          }
          const reasons = new Set<string>()
          const bounded = <T>(items: T[], field: string) => {
            if (items.length > MAX_COLLECTION_ITEMS) reasons.add(field)
            return items.slice(0, MAX_COLLECTION_ITEMS)
          }
          const text = (value: string, field: string) => {
            if (value.length > MAX_TEXT_LENGTH) reasons.add(field)
            return value.slice(0, MAX_TEXT_LENGTH)
          }
          yield* ctx.ask({
            permission: "repository_overview",
            patterns: [instance.directory],
            always: ["*"],
            metadata: { path: instance.directory },
          })
          const entries = yield* fs.readDirectoryEntries(instance.directory)
          const manifest = entries.some((entry) => entry.type === "file" && entry.name === "package.json")
            ? yield* readPackageMetadata(instance.directory)
            : null
          const explicit =
            typeof manifest?.packageManager === "string"
              ? /^(bun|pnpm|yarn|npm)@(\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?)$/.exec(
                  manifest.packageManager,
                )
              : null
          const lockfiles = entries
            .filter((entry) => entry.type === "file" && MANAGERS.has(entry.name))
            .map((entry) => entry.name)
            .sort()
          const managers = new Set(lockfiles.map((file) => MANAGERS.get(file)!))
          const declaration = Option.getOrNull(Schema.decodeUnknownOption(WorkspaceDeclaration)(manifest?.workspaces))
          const patterns = declaration === null ? [] : "packages" in declaration ? declaration.packages : declaration
          const workspacePatterns = bounded(
            [
              ...new Set(
                patterns.flatMap((pattern) => {
                  // Only relative, in-repository patterns are eligible. Never follow symlinks.
                  if (path.posix.isAbsolute(pattern) || path.win32.isAbsolute(pattern) || /[\\!]/.test(pattern))
                    return []
                  const segments = pattern.split("/").filter((segment) => segment !== "." && segment !== "")
                  if (!segments.length || segments.some((segment) => segment === ".." || EXCLUDED.has(segment)))
                    return []
                  if (pattern.length > MAX_TEXT_LENGTH) {
                    reasons.add("workspacePatternLength")
                    return []
                  }
                  return [segments.join("/")]
                }),
              ),
            ].sort(),
            "workspacePatterns",
          )
          const budget = { remaining: MAX_WORKSPACE_STEPS, matches: new Set<string>(), reasons }
          for (const pattern of workspacePatterns) {
            yield* resolveWorkspaces(fs, instance.directory, pattern.split("/"), budget)
          }
          const workspaces = yield* Effect.forEach(
            bounded([...budget.matches].filter((directory) => directory !== instance.directory).sort(), "workspaces"),
            (directory) =>
              Effect.gen(function* () {
                const files = yield* fs.readDirectoryEntries(directory).pipe(Effect.catch(() => Effect.succeed([])))
                const child = files.some((entry) => entry.type === "file" && entry.name === "package.json")
                  ? yield* readPackageMetadata(directory)
                  : null
                return {
                  path: path.relative(instance.directory, directory).split(path.sep).join("/"),
                  name: typeof child?.name === "string" && child.name.trim() ? text(child.name, "workspaceName") : null,
                  technologies: detectTechnologies(files, child),
                }
              }),
          )
          const technologies = [detectTechnologies(entries, manifest), ...workspaces.map((item) => item.technologies)]
          // Technology evidence belongs to the repository, not to workspace
          // membership: a literal declaration can become stale after a rename.
          const detected = new Set([
            instance.directory,
            ...workspaces.map((item) => path.join(instance.directory, item.path)),
          ])
          const directories = [instance.directory]
          for (let index = 0; index < directories.length && index < MAX_TECHNOLOGY_DIRECTORIES; index++) {
            const directory = directories[index]
            const files =
              directory === instance.directory
                ? entries
                : yield* fs.readDirectoryEntries(directory).pipe(
                    Effect.catch(() => {
                      reasons.add("technologyRead")
                      return Effect.succeed([])
                    }),
                  )
            if (!detected.has(directory)) {
              const child = files.some((entry) => entry.type === "file" && entry.name === "package.json")
                ? yield* readPackageMetadata(directory)
                : null
              technologies.push(detectTechnologies(files, child))
            }
            directories.push(
              ...files
                .filter((entry) => entry.type === "directory" && !EXCLUDED.has(entry.name))
                .map((entry) => path.join(directory, entry.name))
                .sort(),
            )
          }
          if (directories.length > MAX_TECHNOLOGY_DIRECTORIES) reasons.add("technologyTraversal")
          const overview = {
            root: text(instance.directory, "root"),
            name: text(path.basename(instance.directory), "name"),
            workspacePatterns,
            workspaces: workspaces.map((item) => ({ path: item.path, name: item.name })),
            languages: [...new Set(technologies.flatMap((item) => item.languages))].sort(),
            frameworks: [...new Set(technologies.flatMap((item) => item.frameworks))].sort(),
            package: manifest
              ? {
                  name:
                    typeof manifest.name === "string" && manifest.name.trim()
                      ? text(manifest.name, "packageName")
                      : null,
                }
              : null,
            packageManager: explicit
              ? {
                  name: explicit[1],
                  version: text(explicit[2], "packageManagerVersion"),
                  source: "package.json#packageManager",
                }
              : managers.size === 1
                ? { name: MANAGERS.get(lockfiles[0])!, version: null, source: lockfiles[0] }
                : null,
            folders: bounded(
              entries
                .filter((entry) => entry.type === "directory" && !EXCLUDED.has(entry.name))
                .map((entry) => entry.name)
                .sort(),
              "folders",
            ),
            importantFiles: bounded(
              entries
                .filter((entry) => entry.type === "file")
                .flatMap((entry) => {
                  const kind = /^README/i.test(entry.name) ? ("readme" as const) : FILES.get(entry.name)
                  return kind ? [{ path: entry.name, kind }] : []
                })
                .sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0)),
              "importantFiles",
            ),
            truncated: false,
            truncationReasons: [] as string[],
          }
          overview.truncated = reasons.size > 0
          overview.truncationReasons = [...reasons].sort()
          // Remove whole entries rather than cutting serialized JSON into an invalid preview.
          while (Buffer.byteLength(JSON.stringify(overview, null, 2)) > MAX_OUTPUT_BYTES) {
            const field = (["workspaces", "workspacePatterns", "importantFiles", "folders"] as const)
              .filter((key) => overview[key].length > 0)
              .sort((a, b) => JSON.stringify(overview[b]).length - JSON.stringify(overview[a]).length)[0]
            if (!field) break
            overview[field].pop()
            reasons.add("outputBytes")
            reasons.add(field)
            overview.truncated = true
            overview.truncationReasons = [...reasons].sort()
          }
          return {
            title: "Repository overview",
            metadata: { overview, truncated: overview.truncated },
            output: JSON.stringify(overview, null, 2),
          }
        }).pipe(Effect.orDie),
    }
  }),
)

function detectTechnologies(entries: FSUtil.DirEntry[], manifest: typeof PackageMetadata.Type | null) {
  return {
    languages: entries.flatMap((entry) => {
      if (entry.type !== "file") return []
      const language = LANGUAGE_FILES.get(entry.name) ?? LANGUAGES.get(LANGUAGE_EXTENSIONS[path.extname(entry.name)])
      return language ? [language] : []
    }),
    frameworks: [manifest?.dependencies, manifest?.devDependencies].flatMap((dependencies) => {
      if (!dependencies || typeof dependencies !== "object" || Array.isArray(dependencies)) return []
      return Object.entries(dependencies).flatMap(([name, version]) => {
        const framework = FRAMEWORKS.get(name)
        return framework && typeof version === "string" && version.trim() ? [framework] : []
      })
    }),
  }
}

function resolveWorkspaces(
  fs: FSUtil.Interface,
  directory: string,
  segments: string[],
  budget: { remaining: number; matches: Set<string>; reasons: Set<string> },
): Effect.Effect<void> {
  return Effect.gen(function* () {
    if (budget.remaining === 0) {
      budget.reasons.add("workspaceTraversal")
      return
    }
    budget.remaining--
    if (!segments.length) {
      budget.matches.add(directory)
      return
    }
    const entries = yield* fs.readDirectoryEntries(directory).pipe(Effect.catch(() => Effect.succeed([])))
    const recursive = segments[0] === "**"
    if (recursive) yield* resolveWorkspaces(fs, directory, segments.slice(1), budget)
    for (const entry of entries
      .filter(
        (entry) =>
          entry.type === "directory" &&
          !EXCLUDED.has(entry.name) &&
          (recursive || fs.globMatch(segments[0], entry.name)),
      )
      .sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))) {
      if (budget.remaining === 0) {
        budget.reasons.add("workspaceTraversal")
        break
      }
      yield* resolveWorkspaces(fs, path.join(directory, entry.name), recursive ? segments : segments.slice(1), budget)
    }
  })
}

import { expect } from "bun:test"
import path from "path"
import fc from "fast-check"
import { rename } from "node:fs/promises"
import { Effect } from "effect"
import { LayerNode } from "@opencode-ai/core/effect/layer-node"
import { FSUtil } from "@opencode-ai/core/fs-util"
import { Agent } from "../../src/agent/agent"
import { MessageID, SessionID } from "../../src/session/schema"
import { RepositoryOverviewTool } from "../../src/tool/repository-overview"
import { Tool } from "../../src/tool/tool"
import { Truncate } from "../../src/tool/truncate"
import { TestInstance, withTmpdirInstance } from "../fixture/fixture"
import { testEffect } from "../lib/effect"
// Project 5: Use reproducible generated inputs for mutation testing.
fc.configureGlobal({ seed: 20261111 })

const it = testEffect(LayerNode.compile(LayerNode.group([FSUtil.node, Truncate.node, Agent.node])))
const ctx = {
  sessionID: SessionID.make("ses_property"),
  messageID: MessageID.make("msg_property"),
  agent: "build",
  abort: AbortSignal.any([]),
  messages: [],
  metadata: () => Effect.void,
  ask: () => Effect.void,
} satisfies Tool.Context
// Independent oracle: vary language combinations without importing detection tables.
const languages = fc.uniqueArray(
  fc.constantFrom(
    { ext: "tsx", name: "TypeScript" },
    { ext: "py", name: "Python" },
    { ext: "rs", name: "Rust" },
    { ext: "go", name: "Go" },
    { ext: "java", name: "Java" },
    { ext: "js", name: "JavaScript" },
  ),
  { minLength: 1, maxLength: 6, selector: (item) => item.name },
)
const names = fc.uniqueArray(fc.stringMatching(/^[a-z][a-z0-9]{0,10}$/), { minLength: 1, maxLength: 8 })

const requirements = [
  {
    id: "R1",
    kind: "model/oracle",
    wording:
      "The tool should display the repository's main directories, important files, and detected programming languages.",
  },
  {
    id: "R2",
    kind: "invariant",
    wording: "The tool must exclude dependency directories and sensitive file contents from the overview.",
  },
  {
    id: "R4",
    kind: "round-trip",
    wording:
      "When a file is added and later deleted, rerunning the tool should produce the same repository overview as before, assuming the final repository contents are unchanged.",
  },
  {
    id: "R5",
    kind: "metamorphic",
    wording:
      "When a directory is renamed without changing its contents, the overview must update the affected directory paths while preserving unrelated programming language and framework information.",
  },
]

requirements.forEach((requirement) => {
  it.live(`${requirement.id} (${requirement.kind}): ${requirement.wording}`, () =>
    Effect.gen(function* () {
      const services = yield* Effect.context<FSUtil.Service | Agent.Service | Truncate.Service>()
      // Each sample and shrink gets a fresh scoped instance. Capture Effect services
      // before crossing fast-check's Promise callback boundary; preserve failures.
      yield* Effect.promise(() =>
        fc.assert(
          fc.asyncProperty(
            names,
            languages,
            fc.boolean(),
            fc.stringMatching(/^[a-zA-Z0-9]{8,32}$/),
            async (folders, evidence, workspace, token) => {
              await Effect.gen(function* () {
                const test = yield* TestInstance
                const fs = yield* FSUtil.Service
                if (requirement.id === "R1") {
                  // Every case includes the P3 nested frontend/backend example,
                  // without workspace declarations. Vary depth, names, and extra languages.
                  const nested = folders.slice(0, 3).join("/")
                  yield* fs.ensureDir(path.join(test.directory, "frontend", nested))
                  yield* fs.ensureDir(path.join(test.directory, "backend", nested))
                  yield* fs.writeJson(path.join(test.directory, "package.json"), {})
                  yield* fs.writeFileString(path.join(test.directory, "frontend", nested, `${token}.tsx`), "")
                  yield* fs.writeFileString(path.join(test.directory, "backend", nested, `${token}.py`), "")
                  yield* Effect.forEach(evidence, (item) =>
                    fs.writeFileString(
                      path.join(test.directory, workspace ? "frontend" : "backend", nested, `main.${item.ext}`),
                      "",
                    ),
                  )
                  const info = yield* RepositoryOverviewTool
                  const tool = yield* info.init()
                  const result = yield* tool.execute({}, ctx)
                  expect(result.metadata.overview.folders).toEqual(["backend", "frontend"])
                  expect(result.metadata.overview.importantFiles).toEqual([{ path: "package.json", kind: "manifest" }])
                  expect(result.metadata.overview.languages).toEqual(
                    [...new Set(["TypeScript", "Python", ...evidence.map((item) => item.name)])].sort(),
                  )
                  expect(result.metadata.overview.workspaces).toEqual([])
                  expect(result.metadata.overview.truncated).toBe(false)
                  expect(JSON.parse(result.output)).toEqual(result.metadata.overview)
                  return
                }
                if (requirement.id === "R5") {
                  // Every sample exercises a stale literal declaration, without
                  // editing any files during the user/ -> client/ rename.
                  const nested = folders.slice(0, 3).join("/")
                  yield* fs.ensureDir(path.join(test.directory, "user", nested))
                  yield* fs.ensureDir(path.join(test.directory, "unrelated"))
                  yield* fs.writeJson(path.join(test.directory, "package.json"), {
                    workspaces: ["user"],
                    devDependencies: { vue: "3" },
                  })
                  yield* fs.writeJson(path.join(test.directory, "user/package.json"), { dependencies: { react: "19" } })
                  yield* fs.writeFileString(path.join(test.directory, "main.js"), "")
                  yield* Effect.forEach(evidence, (item) =>
                    fs.writeFileString(path.join(test.directory, "user", nested, `main.${item.ext}`), ""),
                  )
                  yield* Effect.forEach(evidence, (item) =>
                    fs.writeFileString(path.join(test.directory, "user", `main.${item.ext}`), ""),
                  )
                  // Root-of-workspace evidence makes the old implementation's
                  // loss of React and Python after the rename independently visible.
                  yield* fs.writeFileString(path.join(test.directory, "user/main.py"), "")
                  const info = yield* RepositoryOverviewTool
                  const tool = yield* info.init()
                  const before = yield* tool.execute({}, ctx)
                  expect(before.metadata.overview.languages).toEqual(
                    [...new Set(["JavaScript", "Python", ...evidence.map((item) => item.name)])].sort(),
                  )
                  expect(before.metadata.overview.frameworks).toEqual(["React", "Vue"])
                  expect(before.metadata.overview.workspaces).toEqual([{ path: "user", name: null }])
                  expect(before.metadata.overview.truncated).toBe(false)
                  yield* Effect.promise(() =>
                    rename(path.join(test.directory, "user"), path.join(test.directory, "client")),
                  )
                  const after = yield* tool.execute({}, ctx)
                  expect(after.metadata.overview).toEqual({
                    ...before.metadata.overview,
                    folders: ["client", "unrelated"],
                    // Membership must be truthful: client does not match "user".
                    workspaces: [],
                  })
                  expect(JSON.parse(after.output)).toEqual(after.metadata.overview)
                  return
                }
                yield* Effect.forEach(folders, (name) => fs.ensureDir(path.join(test.directory, `dir-${name}`)))
                yield* fs.writeJson(path.join(test.directory, "package.json"), {
                  workspaces: workspace ? ["dir-*"] : [],
                  dependencies: workspace ? {} : { react: "19" },
                })
                const directory = workspace ? path.join(test.directory, `dir-${folders[0]}`) : test.directory
                if (workspace) {
                  yield* fs.writeJson(path.join(directory, "package.json"), { dependencies: { react: "19" } })
                }
                yield* Effect.forEach(evidence, (item) =>
                  fs.writeFileString(path.join(directory, `main.${item.ext}`), ""),
                )
                const info = yield* RepositoryOverviewTool
                const tool = yield* info.init()
                const before = yield* tool.execute({}, ctx)
                expect(before.metadata.overview.languages).toEqual(evidence.map((item) => item.name).sort())
                expect(before.metadata.overview.frameworks).toEqual(["React"])
                expect(before.metadata.overview.truncated).toBe(false)
                expect(JSON.parse(before.output)).toEqual(before.metadata.overview)
                if (requirement.id === "R2") {
                  // Add every excluded directory at root and inside a declared workspace.
                  // Random secrets and hostile metadata reveal content or traversal leaks.
                  const secret = `PRIVATE_SENTINEL_${token}`
                  yield* fs.writeFileString(path.join(test.directory, ".env"), `API_KEY=${secret}`)
                  yield* Effect.forEach(
                    [
                      "node_modules",
                      ".git",
                      "dist",
                      "build",
                      "coverage",
                      ".next",
                      ".nuxt",
                      ".turbo",
                      ".cache",
                      "target",
                      "vendor",
                      ".venv",
                      "venv",
                      "__pycache__",
                    ].flatMap((name) => [name, `dir-${folders[0]}/${name}`]),
                    (name) =>
                      Effect.gen(function* () {
                        yield* fs.ensureDir(path.join(test.directory, name))
                        yield* fs.writeJson(path.join(test.directory, name, "package.json"), {
                          name: secret,
                          dependencies: { vue: "3" },
                        })
                        yield* fs.writeFileString(path.join(test.directory, name, "leak.py"), secret)
                      }),
                  )
                  // Include wildcard traversal so exclusion is tested during resolution.
                  yield* fs.writeJson(path.join(test.directory, "package.json"), {
                    workspaces: ["*", "*/*"],
                    dependencies: { react: "19" },
                  })
                  const after = yield* tool.execute({}, ctx)
                  expect(after.output).not.toContain(secret)
                  expect(after.output).not.toContain(".env")
                  expect(after.metadata.overview.folders).toEqual(before.metadata.overview.folders)
                  expect(after.metadata.overview.workspaces).toEqual(
                    folders
                      .map((name) => ({ path: `dir-${name}`, name: null }))
                      .sort((a, b) => (a.path < b.path ? -1 : 1)),
                  )
                  expect(after.metadata.overview.languages).toEqual(before.metadata.overview.languages)
                  expect(after.metadata.overview.frameworks).toEqual(["React"])
                  return
                }

                if (requirement.id === "R4") {
                  // A non-README file must not change the important-files overview.
                  // This catches regex mutants that remove the beginning-of-name anchor.
                  const unrelated = path.join(test.directory, `NOTREADME-${token}.md`)
                  yield* fs.writeFileString(unrelated, "unrelated")
                  const ignored = yield* tool.execute({}, ctx)
                  expect(ignored.output).toBe(before.output)
                  expect(ignored.metadata).toEqual(before.metadata)
                  yield* fs.remove(unrelated)

                  // A recognized README must change the overview.
                  const readme = path.join(test.directory, `README-${token}.md`)
                  yield* fs.writeFileString(readme, "temporary")
                  expect((yield* tool.execute({}, ctx)).output).not.toBe(before.output)

import { describe, expect } from "bun:test"
import path from "path"
import { Effect } from "effect"
import { LayerNode } from "@opencode-ai/core/effect/layer-node"
import { FSUtil } from "@opencode-ai/core/fs-util"
import { Agent } from "../../src/agent/agent"
import { InstanceState } from "../../src/effect/instance-state"
import { MessageID, SessionID } from "../../src/session/schema"
import {
  MAX_COLLECTION_ITEMS,
  MAX_OUTPUT_BYTES,
  MAX_TEXT_LENGTH,
